type ExpandedShow = Pick<Show,"id"|"title"|"titleZh"|"years"|"completedYear"|"genre"|"network"|"seasons"|"tier"|"strengths"|"reason"|"barrier"|"audience"|"critics"|"taste"> & {
  imdb: string;
  emmySlug: string;
  award?: { year: string; organization: string; name: string };
};

const expanded = (show: ExpandedShow): Show => ({
  ...show,
  awards: show.award ? [show.award] : [],
  feelings: [],
  tone: [],
  sources: links(show.title, show.imdb, show.emmySlug),
  reviewedAt: "2026-08-11",
});

type ResearchedShow = Omit<Show, "audience" | "critics" | "awards" | "taste" | "feelings" | "tone" | "sources" | "reviewedAt"> & {
  sourceName: string;
  sourceUrl: string;
  award?: { year: string; organization: string; name: string };
};

const researched = (show: ResearchedShow): Show => {
  const strengthText = show.strengths.join("、");
  const firstBarrier = show.barrier.split("；")[0].replace(/。$/, "");
  const experimental = /形式|創新|風格|想像力/.test(strengthText);
  const systemic = /制度|世界|跨世代|歷史/.test(strengthText);
  const complete = /完整度|收尾/.test(strengthText);
  return {
    ...show,
    audience: `長期觀眾最常珍惜它的${show.strengths[0]}與${show.strengths[1]}；是否投入得下去，往往取決於能不能接受${firstBarrier}。`,
    critics: `創作與評論討論主要集中在${strengthText}；這也是本站將它留進選庫的核心依據。`,
    awards: show.award ? [show.award] : [],
    taste: [systemic ? "制度與世界" : "人物親密感", complete ? "封閉完整" : "留白曖昧", experimental ? "形式實驗" : "熟悉類型", /犯罪|科幻|政治|歷史/.test(show.genre) ? "挑戰與不安" : "情緒安慰"],
    feelings: [],
    tone: [],
    sources: [
      { label: "觀眾", sources: [
        { name: "IMDb 觀眾評論", url: `https://www.imdb.com/find/?q=${encodeURIComponent(show.title)}` },
        { name: "Reddit 討論索引", url: `https://www.reddit.com/search/?q=${encodeURIComponent(show.title + " TV")}` },
      ] },
      { label: "影評", sources: [{ name: "Rotten Tomatoes", url: `https://www.rottentomatoes.com/search?search=${encodeURIComponent(show.title)}` }] },
      { label: "主創", sources: [{ name: show.sourceName, url: show.sourceUrl }] },
    ],
    reviewedAt: "2026-08-14",
  };
};

