export const tiers: Tier[] = ["經典核心", "重要作品", "獨特之作"];
export const categories: Category[] = ["犯罪", "劇情", "喜劇", "歷史", "政治", "科幻", "動畫", "運動"];
const categoryByShow: Record<string, Category> = {
  "the-wire":"犯罪", "six-feet-under":"劇情", "breaking-bad":"犯罪", "mad-men":"劇情",
  "the-sopranos":"犯罪", "succession":"劇情", "band-of-brothers":"歷史", "the-americans":"政治",
  "fleabag":"喜劇", "chernobyl":"歷史", "the-west-wing":"政治", "the-shield":"犯罪",
  "the-office":"喜劇", "arrested-development":"喜劇", "battlestar-galactica":"科幻", "deadwood":"劇情",
  "better-call-saul":"犯罪", "the-good-place":"喜劇", "bojack-horseman":"動畫", "the-queens-gambit":"劇情",
  "rectify":"劇情", "friday-night-lights":"運動",
  "twin-peaks":"劇情", "the-x-files":"科幻", "lost":"科幻", "downton-abbey":"劇情",
  "game-of-thrones":"劇情", "the-leftovers":"劇情", "mr-robot":"犯罪", "orange-is-the-new-black":"喜劇",
  "the-crown":"歷史", "dark":"科幻", "peaky-blinders":"犯罪", "narcos":"犯罪",
  "rome":"歷史", "the-pacific":"歷史", "olive-kitteridge":"劇情", "unbelievable":"犯罪",
  "friends":"喜劇", "er":"劇情", "buffy":"劇情", "the-good-wife":"政治", "person-of-interest":"科幻",
};
export const categoryOf = (show: Show): Category => {
  if (categoryByShow[show.id]) return categoryByShow[show.id];
  if (show.genre.includes("犯罪") || show.genre.includes("警匪") || show.genre.includes("監獄")) return "犯罪";
  if (show.genre.includes("喜劇")) return "喜劇";
  if (show.genre.includes("歷史") || show.genre.includes("時代") || show.genre.includes("西部")) return "歷史";
  if (show.genre.includes("政治") || show.genre.includes("諜報")) return "政治";
  if (show.genre.includes("科幻")) return "科幻";
  if (show.genre.includes("動畫")) return "動畫";
  if (show.genre.includes("運動")) return "運動";
  return "劇情";
};
